// Clean-room generalized vector First Fit bin-packing profile.
use core::ptr;const N:usize=32;const D:usize=4;const INPUT:usize=130;const FIELDS:usize=161;
fn put(out:*mut u8,at:usize,x:i64){let b=x as u64;for i in 0..8{unsafe{ptr::write(out.add(at+i),(b>>(8*i))as u8);}}}
#[no_mangle]
pub unsafe extern "C" fn vector_bin_packing(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<2||length>INPUT{return -1;}let nn=*input;let dd=*input.add(1);if nn<1||nn>32||dd<1||dd>4||length!=2+(nn*dd)as usize{return -1;}let n=nn as usize;let d=dd as usize;for i in 0..n*d{let x=*input.add(2+i);if x<0||x>1000{return -1;}}let mut load=[[0i64;D];N];let mut assignment=[0usize;N];let mut bins=0usize;for item in 0..n{let mut chosen=bins;for b in 0..bins{let mut fits=true;for q in 0..d{if load[b][q]+*input.add(2+item*d+q)>1000{fits=false;}}if fits{chosen=b;break;}}if chosen==bins{bins+=1;}assignment[item]=chosen;for q in 0..d{load[chosen][q]+=*input.add(2+item*d+q);}}let mut staged=[0i64;FIELDS];let mut count=0;staged[count]=bins as i64;count+=1;for i in 0..n{staged[count]=assignment[i]as i64;count+=1;}for b in 0..bins{for q in 0..d{staged[count]=load[b][q];count+=1;}}if output.is_null()||capacity<8*count{return -2;}for i in 0..count{put(output,8*i,staged[i]);}(8*count)as i64}
